WFJ.Data.add("quest", {
  [7003] = { "Giganti rimpiccioliti", "Usa l'⟦Zorbin's Ultra-Shrinker=Ultra Riduttore di Zorbin⟧ per rimpicciolire i giganti di qualsiasi tipo che trovi a Feralas, rendendoli più gestibili. Porta 15 Residuo di Miniaturizzazione, che trovi sulle versioni rimpicciolite di questi giganti, a Zorbin Fandazzle, ai moli della Costa dell'Oblio, a Feralas.", "Se resto qui fuori, dovrò fare qualcosa per i giganti! Di certo non fanno bene agli affari, no?\n\nSto lavorando a una variante di un raggio rimpicciolente gnomesco, ma per costruirlo uso i superiori progressi tecnologici dei GOBLIN! Per evitarmi inconvenienti come la morte, vorrei che lo provassi tu su uno qualsiasi dei giganti di Feralas. Dopo averli rimpiccioliti, dovresti trovare su di loro del residuo di miniaturizzazione: portamene un po'!", "Il residuo di miniaturizzazione, te lo assicuro, è una merce preziosa per l'ingegneria! Be', è prezioso nel senso che mi aiuta a far sì che il raggio non faccia qualcosa di deludente come esplodere in mano a chi lo usa.\n\nOh, intendo i raggi diversi da quello che ho dato a te. Assolutamente!", "Splendifantastico! Non solo sono felice di vederti tornare con il residuo, ma anche con tutte le appendici principali intatte! Cioè, be', non c'è mai stato alcun pericolo a usare l'Ultra Riduttore, giusto?\n\nApprezzo davvero l'impegno che ci hai messo per me, {name}. Sei davvero amic<o/a> dei goblin di tutto il mondo. Accetta questo come segno della mia gratitudine!", 0x236b774b, 0xee4452cf, 0x95a0e065, 0xfba8b795, 0xfdd0c9ae, "....." },
  [7021] = { "Babbo Inverno è arrivato!", "Parla con Babbo Inverno: si trova vicino all'area dei venditori della Masseria Buongusto, a Orgrimmar.", "Buon Grande Inverno, amico! Non dimenticare di salutare Babbo Inverno, che al momento si trova a Orgrimmar! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono Babbo Inverno e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0x9a9ce503, 0x591cc909, 0x68b6c09d, nil, 0x296b27e3, "...m." },
  [7022] = { "Babbo Inverno è arrivato!", "Parla con Babbo Inverno: si trova vicino all'area dei venditori della Masseria Buongusto, a ⟦Ironforge=Forgiardente⟧.", "Buon Grande Inverno, amico! Non dimenticare di salutare Babbo Inverno! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono Babbo Inverno e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0xddbfaa79, 0x01d48083, 0xba4aa7ab, nil, 0x296b27e3, "...m." },
  [7023] = { "Babbo Inverno è arrivato!", "Parla con Babbo Inverno: si trova vicino all'area dei venditori della Masseria Buongusto, a ⟦Ironforge=Forgiardente⟧.", "Buon Grande Inverno, amico! Non dimenticare di salutare Babbo Inverno, che al momento si trova a ⟦Ironforge=Forgiardente⟧! Se quest'anno sei stat<o/a> buon<o/a>, riceverai dei dolcetti meravigliosi nel giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi quest'anno è stato buono. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono Babbo Inverno e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0xddbfaa79, 0x01d48083, 0x79ea1c26, nil, 0x296b27e3, "...m." },
  [7024] = { "Babbo Inverno è arrivato!", "Parla con Babbo Inverno: si trova vicino all'area dei venditori della Masseria Buongusto, a Orgrimmar.", "Buon Grande Inverno, amico! Non dimenticare di salutare Babbo Inverno, che al momento si trova a Orgrimmar! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno della Festa del Grande Inverno. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto!", nil, "Oh oh oh, salve. Sono Babbo Inverno e, per gentile concessione della brava gente della Masseria Buongusto... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina della Masseria Buongusto\"... ti auguro una fantastica Festa del Grande Inverno.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti dalla Masseria Buongusto come regalo per la Festa del Grande Inverno. Urrà.", 0x9a9ce503, 0x591cc909, 0x68b6c09d, nil, 0x296b27e3, "...m." },
  [7025] = { "Dolcetti per Babbo Inverno", "Porta 5 Pan di Zenzero e un ⟦Ice Cold Milk=Latte Ghiacciato⟧ a Babbo Inverno a ⟦Ironforge=Forgiardente⟧.", "Ehi, puoi fare un favore a Babbo Inverno, ehm, <bimbo/bimba>?\n\nNon per parlare di me in terza persona senza motivo, ma Babbo Inverno è all'opera da tutto il giorno e un dolcetto gli farebbe proprio comodo. Qualche biscotto di pan di zenzero e del latte ghiacciato per mandarli giù sarebbero proprio l'ideale. Credi di poter dare una mano a Babbo Inverno e andarmene a prendere un po'?", "Tutto questo parlare di dolcetti mi ha fatto venire voglia di mangiarne qualcuno. Mmmm... biscotti di pan di zenzero e latte...", "Sei proprio un bell'aiutante per il vecchio Babbo Inverno, {name}. Buona Festa del Grande Inverno.\n\nEcco un pensierino... sai, per il disturbo.", 0xec79af5f, 0x98d20954, 0xd3822e00, 0x11c73f24, 0x004980cd, ".....", nil, nil, 0xcc6e16c8, nil, nil },
  [7028] = { "Mali contorti", "Raccogli 25 Sculture di Cristallo Teradrico per Willow, a ⟦Desolace=Desolanda⟧.", "Le caverne di cristallo di Terramok si trovano a ovest, nel profondo di Maraudon... È un luogo antico, ricco di storia. E io intendo metterci le mani sopra, almeno in parte, {class}. Dietro le porte gigantesche giacciono nascoste reliquie degli Dei Antichi.\n\nSe sei dispost<o/a> ad affrontare i mali contorti che si trovano a Maraudon, credo di poterti ricompensare a dovere. Raccogli le sculture di cristallo teradrico che trovi e riportale a me.\n\nUna volta avute le sculture, potrò... studiarle. Questi poteri sono rimasti assopiti troppo a lungo...", "Niente domande!\n\nSai cosa ti ho chiesto.", "Ah ah ah! Lo sapevo che saresti tornat<o/a>.\n\n<Willow borbotta.>\n\n...Così facile da convincere.\n\n...Farebbe qualsiasi cosa per il giusto prezzo. Eh eh eh...", 0xeb949bcd, 0x2ae5de19, 0x1db4989e, 0x6691d3a6, 0xc35764ff, "....." },
  [7029] = { "La corruzione di Vyletongue", "Riempi la ⟦Coated Cerulean Vial=Fiala Cerulea Ricoperta⟧ alla pozza di cristallo arancione di Maraudon.\n\nUsa la ⟦Filled Cerulean Vial=Fiala Cerulea Piena⟧ sulle Vylestem Vine per costringere i Noxxious Scion corrotti a uscire allo scoperto.\n\nCura 8 piante uccidendo i Noxxious Scion, poi torna da Vark Battlescar, a ⟦Shadowprey Village=Predombra⟧.", "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, soffocando la crescita di molte delle piante al loro interno.\n\nPrendi questa fiala, {name}. Riempila alla pozza di cristallo arancione che si trova dentro le caverne; il rivestimento interno della fiala neutralizzerà le tossine, trasformando il liquido in un rimedio curativo.\n\nTrova le viti Gamboatroce nelle caverne arancioni e versa su di esse il liquido purificato. La corruzione verrà purgata dalla pianta, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...", "Se riesci a curare la pianta, ricomincerà a crescere. Dobbiamo fare il possibile, {name}...", "Grazie di avermela riportata, {name}. Con il liquido rimasto che mi hai portato potrò continuare i miei studi.\n\nC'è ancora molto da fare, ma hai aiutato a curare parte della corruzione che Vyletongue ha diffuso in Maraudon. Ti prego, prendi questo con la mia gratitudine.", 0x7d91904f, 0x2b955e84, 0xe082ee66, 0x364cece8, 0x5d10207c, "....." },
  [7041] = { "La corruzione di Vyletongue", "Riempi la ⟦Coated Cerulean Vial=Fiala Cerulea Ricoperta⟧ alla pozza di cristallo arancione di Maraudon.\n\nUsa la ⟦Filled Cerulean Vial=Fiala Cerulea Piena⟧ sulle Vylestem Vine per costringere i Noxxious Scion corrotti a uscire allo scoperto.\n\nCura 8 piante uccidendo i Noxxious Scion, poi torna da Talendria, al ⟦Nijel's Point=Presidio di Nijel⟧.", "Un satiro di nome Vyletongue ha corrotto le caverne di Maraudon, soffocando la crescita di molte delle piante al loro interno.\n\nPrendi questa fiala, {name}. Riempila alla pozza arancione corrotta che si trova dentro le caverne; il rivestimento interno della fiala neutralizzerà le tossine, trasformando il liquido in un rimedio curativo.\n\nTrova le viti Gamboatroce nelle caverne arancioni e versa su di esse il liquido purificato. La corruzione verrà purgata dalla pianta, ma sappi che Vyletongue continuerà a controllarla. Potrebbe usarla contro di te...", "Se riesci a curare la pianta, ricomincerà a crescere. Dobbiamo fare il possibile, {name}...", "Grazie di avermela riportata, {name}. Con il liquido rimasto che mi hai portato potrò continuare i miei studi.\n\nC'è ancora molto da fare, ma hai aiutato a curare parte della corruzione che Vyletongue ha diffuso in Maraudon. Ti prego, prendi questo con la mia gratitudine.", 0x7d91904f, 0xa6b69606, 0xfab7c5bd, 0x364cece8, 0x5d10207c, "....." },
  [7042] = { "Dolci rubati del Grande Inverno", "Trova l'investigatore della Masseria Buongusto scomparso nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Senti... non voglio rovinare la magia della stagione, ma la Masseria Buongusto avrebbe bisogno di un po' di aiuto, del tipo che voi avventurieri siete famosi per dare.\n\nCi manca un'importante spedizione di dolci che doveva rifornirci per la stagione, e ora ci manca anche l'agente della Masseria Buongusto che avevamo mandato sul campo a cercarla! Ti prego: secondo l'ultima notizia, la spedizione era nelle ⟦Alterac Mountains=Montagne d'Alterac⟧, ed è lì che il nostro uomo è andato a cercarla.\n\nVedi se sono lì, sani e salvi!", nil, "M-m-mi senti! Sia l-l-lodato il b-b-bilancio!\n\nNon sono davvero un p-p-pupazzo di neve: mi c-c-chiamo Sacks e l-l-lavoro per la f-f-filiale di ⟦Ironforge=Forgiardente⟧ della Masseria Buongusto... Mi hanno m-m-mandato qui a cercare un p-p-pacco scomparso, quando sono stato attaccato da una c-c-creatura che non avevo mai visto p-p-prima!\n\nChe f-f-freddo...", 0x3874de93, 0xfed7fa48, 0x497a89c9, nil, 0xe02f2537, "...m." },
  [7043] = { "Sei proprio cattivo...", "Trova il ⟦Stolen Treats=Dolce Rubato⟧ e riportalo a Wulmort Jinglepocket a ⟦Ironforge=Forgiardente⟧. Si crede che l'ultimo ad averlo avuto sia l'Abominable Greench, che si trova da qualche parte nelle regioni innevate delle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Una c-c-creatura chiamata «The Abominable Greench» è quella c-c-che ha rubato la nostra spedizione di d-d-dolci, {name}. Ma s-s-sta' attent<o/a>! È lui c-c-che mi ha ridotto in questo s-s-stato, tutto coperto di neve!\n\nTi s-s-servirà un po' d'aiuto per a-a-affrontarlo. L'ho visto g-g-girare dappertutto dove ci sono gli y-y-yeti; di s-s-sicuro è qui da qualche p-p-parte! T-t-trova i dolci, {name}, r-r-riportali alla Masseria Buongusto a ⟦Ironforge=Forgiardente⟧ e d-d-di' loro che ho b-b-bisogno di essere s-s-scongelato!", "{name}, la nostra Festa del Grande Inverno sarà rovinata senza quei dolci per rifornirci! Persino Graccu non potrà condividere i suoi deliziosi pasticci di carne con tutti i bravi bambini e le brave bambine in questa stagione...", "L'hai trovato! Hai salvato la Festa del Grande Inverno della Masseria Buongusto!\n\nPovero Sacks... manderemo di sicuro una squadra lassù a trovare un modo per scongelarlo. Speriamo che torni in tempo per il giorno della Festa; dovrà però recuperare le ore di lavoro perse. Comunque, niente di tutto questo sarebbe stato possibile senza di te!", 0xdc4f5e6e, 0x8c241804, 0x01913b07, 0x5cb087ef, 0x84619c0c, "....." },
  [7044] = { "Leggende di Maraudon", "Recupera le due parti dello ⟦Scepter of Celebras=Scettro di Celebras⟧: la ⟦Celebrian Rod=Verga Celebriana⟧ e il ⟦Celebrian Diamond=Diamante Celebriano⟧.\n\nTrova un modo per parlare con Celebras.", "Un satiro oscuro chiamato lord Vyletongue ha diffuso il suo male in queste caverne tortuose, avvelenando la mente di tutti coloro che vi si trovano. Dimora ancora oltre i cristalli viola.\n\nVyletongue ha anche creato un simbolo vivente della sua corruzione, chiamato Noxxion, che dimora oltre i cristalli arancioni. Insieme hanno rubato le due parti dello scettro di mio fratello. Celebras, mio fratello... vaga alla cieca là dentro, maledetto dalla corruzione.\n\nDevi aiutarlo! Trova i pezzi e parla con mio fratello... in qualche modo.", "Mi sono risvegliato da un incubo che sembrava non dovesse finire mai...", "Ora che hai recuperato le due parti del mio scettro, spero che un giorno Maraudon possa liberarsi della corruzione di Vyletongue.", 0x9af58870, 0xf9e13397, 0x41cb6b05, 0x82ff0f35, 0x9c0b7265, "....." },
  [7045] = { "Un grazie dalla Masseria Buongusto!", "Parla con Babbo Inverno a ⟦Ironforge=Forgiardente⟧.", "Noi della Masseria Buongusto ti siamo grati per aver recuperato i dolci rubati, {name}. Per questo vorremmo offrirti un regalo speciale... consegnato nientemeno che da Babbo Inverno in persona!\n\nTi prego, parla con Babbo Inverno: ti darà il tuo regalo della Festa del Grande Inverno da parte di tutti noi della Masseria Buongusto. Dalla nostra fattoria alla tua tavola, è sempre la bontà genuina della Masseria Buongusto... grazie a te, naturalmente!", nil, "Oh oh oh, salve, avventurier<o/a>!\n\nI goblin mi hanno detto che ti sei guadagnat<o/a> un regalo speciale in queste feste, e sono lieto di dartelo. Ecco qua: buona Festa del Grande Inverno, quest'anno e in tutte le stagioni a venire.", 0xfdb1c16f, 0x466d6e14, 0x1ebc2085, nil, 0xc8c04af1, "...m." },
  [7046] = { "Lo ⟦Scepter of Celebras=Scettro di Celebras⟧", "Assisti Celebras il Redento mentre crea lo ⟦Scepter of Celebras=Scettro di Celebras⟧.\n\nParla con lui quando il rituale sarà concluso.", "Un tempo il mio scettro era per me una fonte di speranza. Il suo potere mi concedeva la libertà di spostarmi rapidamente in queste caverne. Speravo di portare pace allo spirito di mio zio... È un compito che ora affido a te.\n\nPerché le due parti tornino a essere una sola, avrò bisogno del tuo aiuto per compiere il rituale. Seguimi, ti prego, e ascolta le mie istruzioni mentre incanalo l'energia necessaria a riunire la verga e il diamante.\n\nInsieme creeremo di nuovo lo ⟦Scepter of Celebras=Scettro di Celebras⟧!", "Se vuoi ricominciare il rituale, abbandona il nostro primo tentativo e poi parlami di nuovo.", "Prendi questo, e sappi che il potere che ora ti è concesso va usato per il bene. Prosegui il tuo viaggio attraverso le caverne e, con un po' di speranza, troverai i resti di mio zio. Ti attendono molti pericoli, {name}.\n\nParlami di nuovo, se dovesse essercene bisogno.", 0x8ee6a5f3, 0xa2c0701f, 0xdf0c447d, 0x4b5207a1, 0xada0789a, "....." },
  [7067] = { "⟦The Pariah's Instructions=Istruzioni dell'Emarginato⟧", "Leggi le Istruzioni dell'Emarginato. Poi recupera l'⟦Amulet of Union=Amuleto dell'Unione⟧ a Maraudon e riportalo all'Emarginato centauro, nel sud di ⟦Desolace=Desolanda⟧.", "Anche se sono stato esiliato come eretico, le mie convinzioni restano vere: questo basta a spingermi avanti. Ma perché il mio destino si compia, mi serve l'aiuto di un estraneo... qualcuno che non appartenga a nessuna tribù di centauri.\n\nIl compito richiede che qualcuno entri nelle sale sacre di Maraudon, una tomba che il mio popolo protegge e in cui solo i più devoti hanno il permesso di entrare.\n\nSe accetti di aiutarmi, ti basta annuire. Ti passerò una pergamena con le mie istruzioni. Leggila e rifletti sulle mie parole.", "Cosa hai deciso, {name}? Puoi aiutarmi? Metterai piede sul suolo sacro per aiutarmi a forgiare un'unica, grande tribù di centauri!?", "È lui, {race}! È proprio lui! Ora posso cominciare la grande impresa di unire le tribù. Grazie.\n\nPrendi questo per il tuo impegno, ti prego. Spero che la prossima volta che ci incontreremo sarà in circostanze molto diverse.", 0xd8aa8c13, 0x644fa901, 0x17cdfc7b, 0xa3331956, 0x76f3983f, "....." },
  [7068] = { "Frammenti di Cristalli d'Ombra", "Raccogli 10 Frammento di Cristalli d'Ombra a Maraudon e riportali a Uthel'nay a Orgrimmar.", "Magie potenti si trovano nel luogo sacro dei centauri... il luogo sacro di Maraudon. Le tribù di centauri di ⟦Desolace=Desolanda⟧ proteggono quel posto con la vita, ma non possono impedirci di prendere quello che ci serve.\n\nTu, tu vai in questo posto chiamato Maraudon e trovi le creature di roccia fatte di cristalli d'ombra. Tu porti a me i cristalli viola, e Uthel'nay fa qualcosa per te per il tuo tempo.\n\nIl posto è pericoloso, quindi forse tu porti qualche amico.", "Tu trovato i cristalli? Rituali di potere, incantesimi di grande forza: quei cristalli d'ombra forse molto utili in tutti i tipi di magie arcane.", "Ah, questi essere perfetti per mie magie. Ecco, tu prendi uno di questi monili e va' per la tua strada... io avere tanto da studiare.", 0xc66ff161, 0xa2e2dbe6, 0x385bc6e0, 0xcae8139d, 0x09e2939a, "....." },
  [7070] = { "Frammenti di Cristalli d'Ombra", "Raccogli 10 Frammento di Cristalli d'Ombra a Maraudon e riportali all'arcimago Tervosh a Theramore, sulla costa di ⟦Dustwallow Marsh=Acquemorte⟧.", "Di recente ho cominciato a studiare vari cristalli e le loro proprietà arcane. Lady Proudmoore mi ha dato il permesso di chiedere ai viaggiatori diretti in ⟦Desolace=Desolanda⟧ di cercare un luogo chiamato Maraudon. All'interno del tempio in rovina ci sono grandi elementali composti di pietre violacee che ho chiamato cristalli d'ombra.\n\nSe decidi di andare da quelle parti e trovi qualcuno di quei cristalli, te ne sarei molto grato. Potrei perfino ricavarne un monile per te, se lo desideri.", "Hai già fatto il viaggio? Mi rendo conto che sarebbe piuttosto pericoloso, ma se ci riuscissi, ne varrebbe davvero la pena.", "Sono perfetti, {name}. A dire il vero sono tornati di là anche altri avventurieri, e con i loro cristalli sono riuscito a ricavare questi... ti prego, prendine uno per il tuo duro lavoro. E grazie ancora per altri campioni da studiare.", 0xc66ff161, 0xec999ae3, 0x8f09c391, 0x23f22516, 0x340dad0c, "....." },
  [7321] = { "⟦Soothing Turtle Bisque=Zuppa Cremosa di Tartaruga⟧", "Porta 10 pezzi di ⟦Turtle Meat=Carne di Tartaruga⟧ e delle ⟦Soothing Spices=Spezie Esotiche⟧ a Christoph Jeffcoat, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Chi dice che i non morti non sanno niente di cucina? Prendi per esempio la mia ricetta segreta della zuppa di tartaruga. Conosco gente che tornerebbe dal regno dei morti solo per gustarne una scodella! Eh, eh...\n\nA proposito, ultimamente non sono riuscito a prepararne. Andavo io stesso al Lago Lordamere a cacciare le snapjaw, quelle bestiacce, ma non riesco a staccarmi dal mio lavoro qui.\n\nSe mi porti un po' di ⟦Turtle Meat=Carne di Tartaruga⟧ dalle snapjaw e delle Spezie Esotiche, ti mostrerò come si fa!", "Hai trovato gli ingredienti? Te lo dico io, quei vermi dell'Alleanza sono fin troppi da queste parti ormai... Secondo me si sono già avvicinati troppo...", "La mia Zuppa Cremosa di Tartaruga ti scalderà in una notte fredda... se ti interessano queste cose.", 0xc8acfcb2, 0x5b979eb8, 0xb1398037, 0x0b383a67, 0x5b8e08bd, "....." },
  [7383] = { "La corona della terra", "Riempi la ⟦Amethyst Phial=Fiala di Ametista⟧ e riportala a Corithras Moonrage, a Dolanaar.", "Non tutto andava bene a Teldrassil, però. I piani accurati di Staghelm per il nuovo Albero del Mondo si erano realizzati come sperava, ma c'era un piccolo problema, un problema a cui si possono attribuire molti dei guai di Teldrassil.\n\nMa non ne parlerò ancora. Devi visitare l'ultimo pozzo lunare, a nord-ovest, nella Oracle Glade. Sotto i rami dell'Oracle Tree si trova il primo e il più potente dei nostri pozzi. Prendi una fiala della sua acqua e torna da me.", "Insieme ai druidi, l'Oracle Tree e l'arcidruido hanno sorvegliato con cura la crescita di Teldrassil. Ma anche se abbiamo una nuova casa, la nostra vita immortale non ci è stata restituita.", "Trovarsi al cospetto dell'Oracle Tree... è quasi come sentire la saggezza prendere forma. Lasciami continuare il racconto...\n\nQuando Teldrassil fu cresciuto, l'arcidruido si rivolse ai draghi per avere le loro benedizioni, come quelle che i draghi avevano concesso a Nordrassil in tempi antichi. Ma Nozdormu, Signore del Tempo, rifiutò di dare la sua benedizione, rimproverando il druido per la sua arroganza. D'accordo con Nozdormu, anche Alexstrasza rifiutò Staghelm, e senza la sua benedizione la crescita di Teldrassil è stata imperfetta e imprevedibile...", 0x6a9c354f, 0x00e3b1b6, 0xa9b364df, 0xb7686ed0, 0x195e31f7, "....." },
  [7541] = { "Al servizio dell'⟦Horde=Orda⟧", nil, nil, nil, "Ci vorrà tempo perché i nostri studiosi esaminino il pendente che ci hai portato. Ma per il tuo servizio all'⟦Horde=Orda⟧ vorrei offrirti un piccolo pegno.\n\nGrazie, {name}. Le tue azioni portano onore a te e a noi.", 0x585442a8, nil, nil, nil, 0x4652c53f, ".mmm." },
  [7601] = { "Gli ordini di Niby", "Parla con Impsy, a ⟦Felwood=Vilbosco⟧.", "Se devo insegnarti i segreti dell'evocazione di un servitore infernale, devi distruggere Kroshius e portarmi il nucleo infernale dai suoi resti in fiamme. Questo, però, non è facile come sembra. Kroshius si è quasi del tutto consumato. Devi riaccendere il suo cadavere e risollevarlo dalle macerie. Per farlo, però, dovrai raccogliere alcuni componenti da altre entità demoniache.\n\nIl mio imp, Impsy, ti metterà sulla buona strada.", nil, "Oh, cielo, ci risiamo.", 0xfdb31e0d, 0x0c9d6772, 0x56c5c901, nil, 0x34ba2cb4, "...m." },
  [7681] = { "Missione di prova del Cacciatore", "Nutri il tuo animale, poi parla con chi ti ha affidato la missione.", "Lancia Feed Pet sul tuo animale.", nil, nil, 0x746b49f4, 0x2f058422, 0x34b38a3e, nil, nil, "...mm" },
  [7682] = { "Missione di prova del Cacciatore2", "Nutri il tuo animale, poi parla con chi ti ha affidato la missione.", "Lancia Feed Pet sul tuo animale.", nil, nil, 0x92e6d935, 0x2f058422, 0x34b38a3e, nil, nil, "...mm" },
  [7701] = { "RICERCATO: il sovrintendente Maltorius", "Nelle profondità della Fossa delle Scorie della Caldera Magmatica, nella ⟦Searing Gorge=Gorgia Rovente⟧, troverai il nano ⟦Dark Iron=Ferroscuro⟧ traditore, il sovrintendente Maltorius.\n\nUccidi il sovrintendente Maltorius e prendi la sua testa. Riporta la testa al capitano delle vedette Lolo Longstriker, nella ⟦Searing Gorge=Gorgia Rovente⟧, per avere la ricompensa.", "Per ordine de sua eminenza, er sovrintendente Oilfist: l'agente rinnegato della ⟦Thorium Brotherhood=Fratellanza del Torio⟧ e nuovo comandante della squadra ⟦Dark Iron=Ferroscuro⟧ della Fossa delle Scorie della Caldera Magmatica, er sovrintendente Maltorius, dev'esse' ammazzato e la sua testa riportata come prova der fatto.\n\nPe' la ricompensa de 'sta taglia, rivolgersi ar capitano delle vedette Lolo Longstriker.", "Non lo vedi che shono occupato? Cosha *hic* vuoi? *hic*", "Non penshavo che avrei rivishto 'shto brutto muso!\n\nShta perfino meglio shenza il reshto di lui attaccato.\n\nEcco la tua ricompensha *hic*, {race}.", 0x03010d28, 0x0202bf14, 0xa7a8fb6a, 0xf201932b, 0x5c34de3e, "....." },
  [7704] = { "Guarda che dimensioni!", "Porta Chambermaid Pillaclencher's Pillow a Evonice Sootsmoker, nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Bene, bene, bene... Che sorpresa. La cameriera aveva un cuscino gigantesco e tutto decorato, e ora è tuo. Evonice Sootsmoker vorrà di sicuro metterci sopra le sue manine sudicie. Portaglielo e vedi se ti offre qualche regalino per il disturbo.", nil, nil, 0x446e8ded, 0xd6d832a4, 0xe1b953bc, nil, nil, "...mm" },
  [7721] = { "Carburante per il raggio", "Raccogli 10 Nucleo dell'Elementale dell'Acqua dai Sea Elemental e dai Sea Spray lungo la Costa dell'Oblio, a Feralas, e riportali a Zorbin Fandazzle, vicino al molo.", "Se scommetto contro il mio stesso buon senso e resto ad aprire una bottega di ingegneria lungo la Costa dell'Oblio, dovrò occuparmi di questi elementali molesti. Maledetti i poteri elementali senza freno, dico io!\n\nPer mia fortuna, e ora anche per la tua, mi<o/a> speranzos<o/a> agente provocat<ore/rice>, gli elementali sono una fonte ideale di energia grezza per il perfezionamento del mio Ultra Riduttore: dagli una bella lezione, dico io! Mentre lo fai, però, assicurati di conservarmi i nuclei degli elementali dell'acqua!", "Potrei annoiarti con i dettagli tecnici sull'utilità dei nuclei elementali, ma preferisco invogliarti a portare a termine questo importante compito offrendoti monete e premi di valore. Orsù, in verità, hai finito?", "Strabiliantastico! Questi nuclei mi terranno al lavoro per un bel po'. Aggiungi il vantaggio che ora ci sono meno elementali lungo la costa, e forse non piangerò più fino ad addormentarmi al pensiero di aver aperto bottega nel posto forse peggiore che si possa immaginare!\n\nGrazie, {name}, per l'impegno che ci hai messo per me. Anche se finanziariamente mi mette alle strette, lascia che ti mostri un po' di gratitudine in una forma che capirai e apprezzerai... bottino!", 0x809826c8, 0x3172fbce, 0x2e6a8654, 0x00a49bad, 0x0d4b34c8, "....." },
  [7722] = { "Ma che flussante?", "Da qualche parte nella Fossa delle Scorie della Caldera Magmatica troverai il ⟦Secret Plans: Fiery Flux=Progetto Segreto: Flussante Infuocato⟧ che il sovrintendente Maltorius ha rubato. Trova il progetto e riportalo al mastro fabbro Burninate, nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Quando quel bastardo di Maltorius ha lasciato il nostro clan, se n'è andato con qualcosa di più prezioso di un cristallo arcano intatto: la nostra ricetta del flussante infuocato! Ci scommetterei qualsiasi cosa che la ricetta faceva parte dell'accordo per la sua nuova promozione tra i Ferroscuro.\n\nVoglio che tu recuperi i nostri piani segreti, {name}. Sono sicuro che si trovano da qualche parte vicino a Maltorius, nelle profondità della Fossa delle Scorie.", "Hai trovato i piani?", "Spero che gli abbia anche spaccato i denti, {name}. Ragnaros sa che se lo meritava.\n\nOra possiamo passare agli affari.", 0xc07aa3bb, 0x8f132878, 0x336636d3, 0x85bbae45, 0x27d3986a, "....." },
  [7723] = { "Maledette dita gonfie", "Hansel Heavyhands vuole che tu uccida 20 Heavy War Golem.\n\nGli Heavy War Golem si aggirano nelle zone attorno alla Caldera Magmatica, nella ⟦Searing Gorge=Gorgia Rovente⟧. Quando ne avrai uccisi abbastanza, torna da Hansel nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Purtroppo non posso più menar le mani come una volta, per via di 'sto problema delle dita gonfie. Vedi, il clima di quaggiù, insieme alla mancanza di pressione dell'aria, mi fa gonfiare le dita. Sono come giganteschi sanguinacci di Thelsamar, eccome...\n\nTi toccherà sbrigare i miei affari e compagnia bella.\n\nPrimo punto della mia lista: pestare a sangue i golem da guerra pesanti della Gorgia. Datti da fare.", "Li hai pestati?", "Sei <un/una> <bravo/brava> <ragazzo/ragazza>, eccome se lo sei. Ti ho preso un regalino per il disturbo.", 0x1866df92, 0x2dfa4f25, 0xe5c62f10, 0xcbb0cf9d, 0xcf9f67a7, ".....", nil, nil, nil, nil, 0x53921380 },
  [7724] = { "Minaccia infuocata!", "Hansel Heavyhands vuole che tu uccida 20 Greater Lava Spider nella ⟦Searing Gorge=Gorgia Rovente⟧. Trovi i Greater Lava Spider sugli altipiani e nelle pozze di lava della ⟦Searing Gorge=Gorgia Rovente⟧.\n\nTorna da Hansel Heavyhands nella ⟦Searing Gorge=Gorgia Rovente⟧ quando avrai ucciso abbastanza Greater Lava Spider.", "Guarda un po', ogni volta che il vecchio Hansel vuole prendersi un momento per rilassarsi e riflettere sulla sua vita, i pezzi grossi gli rifilano un altro lavoro.\n\nMi tocca pensare, ma dai! Capisci cosa voglio dire? Ma. Dai.\n\nDunque, 'sti grandi ragni di lava stanno facendo una specie di baccano. Oilfist dice che sparano fuoco dal loro... ehm, sì, be', comunque, cose del genere spaventano i bambini.\n\nMi sa che dobbiamo ammazzarli. Anzi, sei tu che devi ammazzarli.", "Aveva ragione? Gli esce dal sedere?", "<Hansel starnutisce.>\n\nMi sa che mi sto prendendo un raffreddore. Maledetto questo clima gelido!", 0xe1aa77fc, 0xf5e8572b, 0x14a3807c, 0x57ac94ac, 0x18ad5817, "....." },
  [7727] = { "Incendiosauri? Chissàchesauri, piuttosto", "Hansel Heavyhands vuole che tu uccida 20 Incendosaur.\n\nTroverai gli Incendosaur nelle pozze di lava all'interno della ⟦The Slag Pit=Fossa delle Scorie⟧. La ⟦The Slag Pit=Fossa delle Scorie⟧ si trova nella Caldera Magmatica della ⟦Searing Gorge=Gorgia Rovente⟧.\n\nTorna da Hansel Heavyhands nella ⟦Searing Gorge=Gorgia Rovente⟧ quando avrai ucciso abbastanza Incendosaur.", "Calli, <ragazzo/ragazza>. I miei calli hanno i calli. Come faccio ad ammazzare qualcosa con i piedi conciati così? Ecco perché mi aiuterai tu.\n\nScrange e Burninate mi hanno incaricato di uccidere quelle bestie, così potranno mandare qualche squadra di spedizione giù nelle pozze di lava della Fossa delle Scorie a esplorare un po'. Pare che laggiù ci siano degli incendiosauri o qualche altra sciocchezza del genere che creano problemi di ogni sorta. Ora muoviti, e non tornare finché gli incendiosauri non saranno estinti.", "<Hansel si massaggia i calli con grande impegno.>\n\nNon startene lì impalat<o/a>, prendi un po' d'olio e una spugna di luffa e mettiti a strofinare 'sti calli.\n\nNon hai una spugna di luffa? Be', allora! Forse è ora che ti mandi a cercarne una?\n\nEhi, dove vai?", "Oh, i miei poveri piedi.\n\nHo pensato che, visto che non avevi una spugna di luffa...", 0xd4823678, 0x244f3d0d, 0xe0116ef8, 0xc2bee4d5, 0x071dfa2a, ".....", nil, nil, 0x64ef711a, nil, nil },
  [7728] = { "RUBATI: ⟦Smithing Tuyere=Tubo per Fucine⟧ e ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧", "Trova e riporta il ⟦Smithing Tuyere=Tubo per Fucine⟧ e il ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧ al coordinatore Scrange, nella ⟦Searing Gorge=Gorgia Rovente⟧.\n\nLe uniche informazioni che hai su questi oggetti sono le seguenti: sono stati di sicuro rubati dai nani ⟦Dark Iron=Ferroscuro⟧. Il ⟦Smithing Tuyere=Tubo per Fucine⟧ è un attrezzo usato dai fabbri, e il ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧ è uno strumento di sorveglianza prezioso per le vedette.", "Sono stati rubati i seguenti oggetti:\n\n*Un tubo per fucine ⟦Dark Iron=Ferroscuro⟧.\n\n*Un ⟦Lookout's Spyglass=Cannocchiale della Vedetta⟧.\n\nViene offerta una ricompensa a chi troverà e restituirà questi oggetti trafugati.\n\nLa ⟦Thorium Brotherhood=Fratellanza del Torio⟧ è certa che questi oggetti siano stati rubati dai nani ⟦Dark Iron=Ferroscuro⟧, invidiosi e senza scrupoli, che abitano la ⟦Searing Gorge=Gorgia Rovente⟧.\n\nIl cannocchiale in questione era un ottimo strumento per le vedette, e il tubo era un attrezzo da fabbro insostituibile.\n\nSe trovi gli oggetti scomparsi, riportali a Scrange.", "Se sei qui per la ricompensa, dovrai darmi la refurtiva.", "Lavoro fantastico! Ora, la tua ricompensa.", 0x64a25f02, 0xa792a255, 0xd964ba68, 0x75ecaf91, 0x700453bf, "....." },
  [7729] = { "OFFERTA DI LAVORO: sfoltire la concorrenza", "Uccidi 15 Dark Iron Taskmaster e 15 Dark Iron Slaver. Quando hai finito, torna dal coordinatore Scrange nella ⟦Searing Gorge=Gorgia Rovente⟧.", "Il coordinatore Scrange cerca qualche brav'uomo e qualche brava donna che aiuti a \"sfoltire la concorrenza\" nella ⟦Searing Gorge=Gorgia Rovente⟧.\n\nSe ti interessa questo incarico, avventurati nella ⟦Searing Gorge=Gorgia Rovente⟧ e massacra ogni Dark Iron Taskmaster e ogni Dark Iron Slaver che vedi.\n\nTorna dal coordinatore Scrange quando i tuoi vestiti saranno abbastanza insanguinati.\n\nSaprai tu quando lo saranno, quindi non chiedere.", "Dovremo pesarti con e senza vestiti, per esserne sicuri.", "15.9 libbre! Potrebbe essere un nuovo record di peso di sangue e budella sui vestiti! Congratulazioni, {class}!", 0x27d0f06d, 0x743a8c0d, 0x9394b676, 0x765dfe1d, 0xd80310ca, "....." },
  [7730] = { "Infestazione di Zukk'ash", "Porta 20 Carapace di Zukk'ash a Hadoken Swiftstrider all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.", "Da quel poco che siamo riusciti a scoprire in ricognizione, crediamo che il nemico a sud degli gnoll sia una razza simile agli insetti. Francamente, che siano senzienti o no è irrilevante. Se sono loro a spingere gli gnoll alla furia contro di noi, allora sono una minaccia grande quanto gli gnoll, se non di più.\n\nSpingiti in profondità dove vivono questi insetti Zukk'ash, un luogo noto come la Fossa Fremente. Riducine il numero e riferiscimi cosa trovi, portando i loro carapaci come prova del tuo lavoro.", "Come va la caccia, {name}? Sei qui per riferirmi il tuo successo?", "Ben fatto, {class}. Anche se la presenza così estesa degli Zukk'ash non sarà fermata con niente di meno di un'invasione su vasta scala, ci hai fatto guadagnare un po' di tempo per mettere a punto una strategia adeguata.\n\nMi assicurerò di far analizzare questi carapaci; dovremo sapere tutto di loro prima di affrontare quello che, purtroppo, si è rivelato un problema molto più grande di quanto avessimo previsto.", 0x932e3026, 0xb72ef59a, 0x883ce546, 0xc0557a8f, 0x83d0e4be, "....." },
  [7731] = { "Sferzaculei", "Sconfiggi Stinglasher nella Fossa Fremente e porta le sue ghiandole a Hadoken Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.", "Durante il sopralluogo nella Fossa Fremente, uno dei nostri esploratori ha riferito di aver visto un insetto gigantesco, molto più grande degli altri avvistati, aggirarsi per quel terreno contorto. Non solo è più grande, ma sembra anche emanare una specie di aura che gli altri insetti non hanno. Gli abbiamo dato un nome: Sferzaculei.\n\nLe interiora di questa bestia sarebbero preziosissime da studiare, mentre cerchiamo il modo migliore di affrontare questa nuova minaccia. Asportagli le ghiandole secretorie e portamele immediatamente!", "Sei riuscit<o/a> ad abbattere Sferzaculei?", "Notevole, {class}... davvero notevole! Se Sferzaculei è davvero una delle loro creature più forti, lo studio di questa bestia si rivelerà assai prezioso col tempo. Ora il mio compito è assicurarmi che ci difendiamo abbastanza a lungo da poterne approfittare.\n\nTi prego, accetta questa taglia come segno di gratitudine da parte di tutto l'accampamento, {name}. Ben fatto.", 0x77138744, 0x4fd44652, 0x73c277a8, 0xb18b3f63, 0xe87d41a1, "....." },
  [7732] = { "Rapporto sugli Zukk'ash", "Consegna il ⟦Camp Mojache Zukk'ash Report=Rapporto di Zukk'ash sull'Accampamento Mojache⟧ a Zilzibin Drumlore. Risiede a The Drag, a Orgrimmar.", "Hai fatto doppiamente bene ad affrontare la minaccia che gli insetti Zukk'ash rappresentano per l'⟦Camp Mojache=Accampamento Mojache⟧. Il pericolo che costituiscono è tutt'altro che finito, e vorrei chiederti un ultimo compito per conto dell'⟦Horde=Orda⟧.\n\nQuesto documento riporta tutte le informazioni che abbiamo raccolto su questi insetti Zukk'ash. Voglio che tu lo consegni a Zilzibin Drumlore, a The Drag, a Orgrimmar. È un esperto di creature aliene come queste; spero che possa fare qualcosa con il sapere che abbiamo raccolto.", "Salute, amico... sembri avere una faccenda urgente. Posso aiutarti in qualche modo?", "Ah, me lo aspettavo. Queste creature che hai affrontato... sono un'antica minaccia che l'⟦Horde=Orda⟧ continua a scegliere di ignorare. Hadoken è stato saggio a portare questo, e te, da me.\n\nGli Zukk'ash non sono altro che creature chiamate silitidi. Alcuni penserebbero che siano solo un fastidio senza cervello, ma lascia che te lo assicuri: sono una minaccia molto, molto peggiore di qualsiasi cosa l'⟦Alliance=Alleanza⟧ possa mettere in campo.\n\nSe hai la volontà e la forza, il tuo aiuto mi farebbe comodo per portare alla luce questa minaccia.", 0x5199ec19, 0xdeed09ff, 0x58b47835, 0x78492e92, 0x2c9e366b, "....." },
  [7733] = { "Qualità superiore", "Porta 10 Rage Scar Yeti Hide a Pratt McGrubben a Feathermoon Stronghold, a Feralas.", "Ho una pista per una fonte di pelli ancora MIGLIORE, se mai è possibile crederci! Nella parte settentrionale di Feralas, nel cuore della ⟦Rage Scar Hold=Tana degli Artiglio Selvaggio⟧, c'è un'altra orda di yeti. Sono molto più duri di quelli che hai affrontato prima, quindi se te la senti di affrontare una sfida più grande, faresti meglio a stare all'erta!\n\nTi ricompenserei generosamente per una pila di dieci delle loro pelli; portamele qui e concluderemo il nostro affare.", "Se queste pelli di yeti Artiglio Selvaggio sono anche solo della qualità di quelle dei loro simili di Valsfregiata, potrebbero essere resistenti quanto il torio!\n\nTi rendi conto?", "Ottimo, ottimo! Queste funzioneranno benissimo: già capisco che saranno molto più dure una volta conciate a dovere.\n\nGrazie ancora per il tuo aiuto, {name}. Ecco, prendi una delle mie ultime creazioni.", 0xa8bb365e, 0x57e69c4f, 0x69ee584c, 0xc4178ba9, 0xc3980197, "....." },
  [7734] = { "Qualità superiore", "Porta 10 Rage Scar Yeti Hide a Jangdor Swiftstrider all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas.", "Ho una pista per una fonte di pelli ancora MIGLIORE, se mai è possibile crederci! Nella parte settentrionale di Feralas, nel cuore della ⟦Rage Scar Hold=Tana degli Artiglio Selvaggio⟧, c'è un'altra orda di yeti. Sono molto più duri di quelli che hai affrontato prima, quindi se te la senti di affrontare una sfida più grande, faresti meglio a stare all'erta!\n\nTi ricompenserei generosamente per una pila di dieci delle loro pelli; portamele qui e concluderemo il nostro affare.", "Se queste pelli di yeti Artiglio Selvaggio sono anche solo della qualità di quelle dei loro simili di Valsfregiata, potrebbero essere resistenti quanto il torio!\n\nTi rendi conto?", "Ottimo, ottimo! Queste funzioneranno benissimo: già capisco che saranno molto più dure una volta conciate a dovere.\n\nGrazie ancora per il tuo aiuto, {name}. Ecco, prendi una delle mie ultime creazioni.", 0xa8bb365e, 0x8a00501d, 0x69ee584c, 0xc4178ba9, 0xe3079241, "....." },
  [7788] = { "Sconfiggi gli invasori!", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Horde=Orda⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e torna dalla sentinella Farsong al ⟦Silverwing Grove=Boschetto degli Alargentea⟧.", "Oltre questa galleria troverai un campo di lotta e tumulto, giovane {class}. L'⟦Horde=Orda⟧ continua a devastare la nostra foresta sacra, abbattendo i sempreverdi per alimentare le sue macchine da guerra.\n\nEntra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difendi la ⟦Silverwing Hold=Rocca di Alargentea⟧. Respingi le forze d'invasione dell'⟦Horde=Orda⟧!\n\nFallo, e otterrai un talismano al merito. Portami un tale talismano, {name}, e ti ricompenserò.", "Hai combattuto nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e difeso la ⟦Silverwing Hold=Rocca di Alargentea⟧?", "Hai dimostrato il tuo valore nei nostri sforzi nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧. Continua a sostenere la causa e portami altri contrassegni d'onore. Fallo, e ti guadagnerai ancora di più la nostra fiducia.", 0x55520e44, 0xfeb46d9a, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [7789] = { "Domare gli usurpatori Alargentea", "Entra nella ⟦Warsong Gulch=Forra dei Cantaguerra⟧ e sconfiggi l'⟦Alliance=Alleanza⟧, ottieni un ⟦Warsong Gulch Mark of Honor=Contrassegno d'Onore della Forra dei Cantaguerra⟧ e portalo al capitano Shatterskull all'⟦Mor'shan Base Camp=Accampamento Mor'shan⟧.", "Le terre selvagge della foresta di ⟦Ashenvale=Valtetra⟧ cederanno alla potenza dell'⟦Horde=Orda⟧, {race}. Nulla di ciò che gli Alargentea dicono o fanno può fermare il nostro imperativo sovrano. Kalimdor appartiene all'⟦Horde=Orda⟧. Come osano cercare di impedirci di raccogliere ciò che è nostro di diritto!\n\nLascia che l'orgoglio ti gonfi il petto mentre stronchi i loro deboli tentativi di rallentare la nostra avanzata. Distruggi le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ e ottieni un contrassegno d'onore dei ⟦Warsong=Cantaguerra⟧. Torna da me con un tale contrassegno, {name}, e sarai ricompensat<o/a>.", "Il sangue dei nostri nemici è un contrassegno d'onore. Ce l'hai un contrassegno del genere?", "<Il capitano Shatterskull ruggisce in trionfo.>\n\nQuanto ancora possono resistere? Quanta altra feccia dell'⟦Alliance=Alleanza⟧ deve perire per mano dell'⟦Horde=Orda⟧ prima che si ritirino? Solo il tempo lo dirà, {race}...", 0x636625b4, 0xc94c2293, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [7791] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza di ⟦Stormwind=Roccavento⟧ per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0xbfdb39e9, 0xde0116d9, ".mm.." },
  [7792] = { "Una donazione di lana", nil, nil, "Al momento accettiamo donazioni di tessuto di lana. Una donazione di sessanta pezzi di tessuto di lana ti varrà la piena riconoscenza di Darnassus per il tuo gesto generoso. Le nostre scorte di lana sono tali che da te ci serviranno solo sessanta pezzi in tutto; dovremmo riuscire a procurarcene abbastanza da altri nel regno per sostenere la nostra raccolta.\n\nSe hai con te i sessanta pezzi di tessuto di lana e sei pront<o/a> a donarli, posso prenderli subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaad71c6f, nil, nil, 0x30fa2bb9, 0xde0116d9, ".mm.." },
  [7793] = { "Una donazione di seta", nil, nil, "Come per la maggior parte degli altri tessuti, le nostre scorte di seta sono ai minimi storici. Le nostre riserve sono tali che da te ci servirebbero in tutto solo sessanta pezze di seta; dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno degli altri.\n\nUn dono generoso come la seta, mi permetto di aggiungere, aumenterebbe di certo la tua reputazione nella comunità! Se hai con te le sessanta pezze di seta e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0xaa4c5243, nil, nil, 0x12099df5, 0xde0116d9, ".mm.." },
  [7794] = { "Una donazione di tessuto magico", nil, nil, "Il tessuto magico scarseggia, e il tuo aiuto ci farebbe comodo per rifornire le scorte! Contando sull'intera comunità, da te ci servirebbe solo una donazione di 60 pezze di tessuto magico per raggiungere il nostro obiettivo. Una simile generosità non passerebbe inosservata a ⟦Stormwind=Roccavento⟧, te lo assicuro!\n\nSe hai con te le sessanta pezze di tessuto magico e sei <pronto/pronta> a donarle, posso prenderle subito.", "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", 0x2c4ad0c3, nil, nil, 0x1ff8b690, 0xde0116d9, ".mm.." },
